-- api_dashboard_batches: gate batches_all on an ongoing production cycle
-- (matching api_fingerling_batch_options_rpc) so closed historical batches
-- never reach the batches page. Replaces the reverted is_synthetic filter.

CREATE OR REPLACE FUNCTION public.api_dashboard_batches(p_farm_id uuid, p_batch_ids bigint[] DEFAULT NULL::bigint[], p_stage system_growth_stage DEFAULT NULL::system_growth_stage, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS TABLE(batch_id bigint, batch_name text, growth_stage system_growth_stage, system_ids bigint[], system_count integer, input_start_date date, input_end_date date, as_of_date date, fish_end double precision, biomass_end double precision, sampling_end_date date, sample_age_days integer, efcr double precision, efcr_latest_date date, efcr_arrow text, feed_total double precision, abw double precision, abw_latest_date date, abw_arrow text, feeding_rate double precision, feeding_rate_latest_date date, feeding_rate_arrow text, mortality_rate double precision, mortality_rate_latest_date date, mortality_rate_arrow text, biomass_density double precision, biomass_density_latest_date date, biomass_density_arrow text, sgr double precision, agr double precision, sgr_arrow text, agr_arrow text, missing_days_count integer, water_quality_rating_average text, water_quality_rating_numeric_average double precision, water_quality_latest_date date, water_quality_arrow text, worst_parameter text, worst_parameter_value double precision, worst_parameter_unit text, cycle_day integer, target_weight_g double precision, target_weight_progress_pct double precision, is_complete boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'analytics', 'private'
AS $function$
with
 batches_all as ( select fb.id as batch_id, coalesce(nullif(fb.name, ''), 'Batch #' || fb.id::text) as batch_name from public.fingerling_batch fb where fb.farm_id = p_farm_id and private.app_rpc_scope_ok(p_farm_id, null::bigint[], null::bigint, p_start_date, p_end_date) and exists (select 1 from public.production_cycle pc where pc.batch_id = fb.id and pc.ongoing_cycle = true) and (p_batch_ids is null or fb.id = any(p_batch_ids)) ),
data_anchor as ( select coalesce(max(dsf.inventory_date), current_date) as last_data_date from analytics.daily_system_facts dsf join batches_all b on b.batch_id = dsf.batch_id ),
bounds as ( select coalesce(p_start_date, da.last_data_date - interval '30 days')::date as start_date, coalesce(p_end_date, da.last_data_date)::date as end_date from data_anchor da ),
period_meta as ( select b.start_date, b.end_date, greatest((b.end_date - b.start_date + 1)::integer, 1) as period_days from bounds b ),
periods as ( select 'current'::text as period_label, pm.start_date, pm.end_date from period_meta pm
  union all
  select 'previous'::text, (pm.start_date - pm.period_days)::date, (pm.start_date - 1)::date from period_meta pm ),
batch_flows as ( select fs.batch_id, fs.system_id, fs.number_of_fish_stocking::double precision as qty_delta from public.fish_stocking fs join batches_all b on b.batch_id = fs.batch_id where fs.system_id is not null and fs.date <= (select end_date from bounds)
  union all
  select ft.batch_id, ft.target_system_id, ft.number_of_fish_transfer::double precision from public.fish_transfer ft join batches_all b on b.batch_id = ft.batch_id where ft.target_system_id is not null and ft.date <= (select end_date from bounds)
  union all
  select ft.batch_id, ft.origin_system_id, -ft.number_of_fish_transfer::double precision from public.fish_transfer ft join batches_all b on b.batch_id = ft.batch_id where ft.origin_system_id is not null and ft.date <= (select end_date from bounds)
  union all
  select fm.batch_id, fm.system_id, -fm.number_of_fish_mortality::double precision from public.fish_mortality fm join batches_all b on b.batch_id = fm.batch_id where fm.system_id is not null and fm.date <= (select end_date from bounds)
  union all
  select fh.batch_id, fh.system_id, -coalesce(fh.number_of_fish_harvest, 0)::double precision from public.fish_harvest fh join batches_all b on b.batch_id = fh.batch_id where fh.system_id is not null and fh.date <= (select end_date from bounds) ),
batch_system_balance as ( select batch_id, system_id, sum(qty_delta) as fish_balance from batch_flows group by batch_id, system_id having sum(qty_delta) > 0 ),
batch_systems as ( select bsb.batch_id, bsb.system_id, s.growth_stage from batch_system_balance bsb join public.system s on s.id = bsb.system_id where s.farm_id = p_farm_id and s.is_active = true and coalesce(s.cage_status, 'occupied'::public.cage_status_enum) <> 'retired'::public.cage_status_enum ),
batch_meta as ( select bs.batch_id, array_agg(distinct bs.system_id order by bs.system_id) as system_ids, count(distinct bs.system_id)::integer as system_count, case when count(distinct bs.growth_stage) = 1 then min(bs.growth_stage) else null end as growth_stage from batch_systems bs group by bs.batch_id ),
batch as ( select ba.batch_id, ba.batch_name, bm.system_ids, bm.system_count, bm.growth_stage from batches_all ba join batch_meta bm on bm.batch_id = ba.batch_id where p_stage is null or exists (select 1 from batch_systems bs2 where bs2.batch_id = ba.batch_id and bs2.growth_stage = p_stage) ),
inv_daily as ( select p.period_label, dsf.inventory_date, dsf.batch_id, sum(dsf.number_of_fish) as fish_count, sum(dsf.biomass_last_sampling) as biomass, case when sum(dsf.biomass_last_sampling) > 0 then sum(coalesce(dsf.abw_last_sampling,0) * coalesce(dsf.biomass_last_sampling,0)) / sum(dsf.biomass_last_sampling) else avg(dsf.abw_last_sampling) end as abw, max(dsf.last_abw_date) as sampling_end_date, case when sum(dsf.biomass_last_sampling) > 0 then sum(coalesce(dsf.feeding_rate,0) * coalesce(dsf.biomass_last_sampling,0)) / sum(dsf.biomass_last_sampling) else avg(dsf.feeding_rate) end as feeding_rate, case when sum(dsf.number_of_fish) > 0 then sum(coalesce(dsf.mortality_rate,0) * coalesce(dsf.number_of_fish,0)) / sum(dsf.number_of_fish) else avg(dsf.mortality_rate) end as mortality_rate, avg(dsf.biomass_density) as biomass_density from periods p join analytics.daily_system_facts dsf on dsf.inventory_date between p.start_date and p.end_date join batches_all b on b.batch_id = dsf.batch_id group by p.period_label, dsf.inventory_date, dsf.batch_id ),
inv_snapshot as ( select distinct on (period_label, batch_id) period_label, batch_id, inventory_date, fish_count as fish_end, biomass as biomass_end, abw, sampling_end_date, feeding_rate, mortality_rate, biomass_density from inv_daily order by period_label, batch_id, inventory_date desc ),
inv_latest as (select * from inv_snapshot where period_label = 'current'),
inv_prev as (select * from inv_snapshot where period_label = 'previous'),
inv_agg as ( select batch_id, count(distinct inventory_date)::integer as days_present from inv_daily where period_label = 'current' group by batch_id ),
inv_period_metrics as ( select period_label, batch_id, case when sum(coalesce(fish_count,0)) > 0 then sum(coalesce(mortality_rate,0) * coalesce(fish_count,0)) / sum(fish_count) else avg(mortality_rate) end as mortality_rate_period, avg(biomass_density) as biomass_density_period, case when sum(coalesce(biomass,0)) > 0 then sum(coalesce(feeding_rate,0) * coalesce(biomass,0)) / sum(biomass) else avg(feeding_rate) end as feeding_rate_period from inv_daily group by period_label, batch_id ),
inv_current_metrics as (select * from inv_period_metrics where period_label = 'current'),
inv_prev_metrics as (select * from inv_period_metrics where period_label = 'previous'),
ps_window as ( select p.period_label, pc.batch_id, ps.date, ps.feed_over_period, ps.biomass_increase_over_period, ps.sgr, ps.agr, ps.days_in_period from periods p join analytics.production_summary ps on ps.date between p.start_date and p.end_date join public.production_cycle pc on pc.cycle_id = ps.cycle_id join batches_all b on b.batch_id = pc.batch_id ),
ps_daily as ( select period_label, batch_id, date, sum(coalesce(feed_over_period,0))::double precision as feed_over_period, greatest(sum(coalesce(biomass_increase_over_period,0)),0)::double precision as biomass_increase_over_period, case when sum(case when sgr is not null then greatest(coalesce(biomass_increase_over_period,0),0) else 0 end) > 0 then sum(coalesce(sgr,0) * greatest(coalesce(biomass_increase_over_period,0),0)) / sum(case when sgr is not null then greatest(coalesce(biomass_increase_over_period,0),0) else 0 end) else null end::double precision as sgr, case when sum(case when agr is not null then greatest(coalesce(biomass_increase_over_period,0),0) else 0 end) > 0 then sum(coalesce(agr,0) * greatest(coalesce(biomass_increase_over_period,0),0)) / sum(case when agr is not null then greatest(coalesce(biomass_increase_over_period,0),0) else 0 end) else null end::double precision as agr, max(days_in_period)::integer as days_in_period from ps_window group by period_label, batch_id, date ),
ps_ranked as ( select *, row_number() over (partition by period_label, batch_id order by date desc) as rn from ps_daily ),
ps_latest as ( select * from ps_ranked where period_label = 'current' and rn = 1 ),
ps_period_metrics as ( select period_label, batch_id, sum(coalesce(feed_over_period,0))::double precision as feed_total, sum(coalesce(feed_over_period,0))::double precision as total_feed_period, sum(coalesce(biomass_increase_over_period,0))::double precision as total_growth_period, case when sum(case when sgr is not null then days_in_period else 0 end) > 0 then sum(case when sgr is not null then sgr * days_in_period else 0 end) / nullif(sum(case when sgr is not null then days_in_period else 0 end), 0) else null end::double precision as sgr_period, case when sum(case when agr is not null then days_in_period else 0 end) > 0 then sum(case when agr is not null then agr * days_in_period else 0 end) / nullif(sum(case when agr is not null then days_in_period else 0 end), 0) else null end::double precision as agr_period from ps_daily group by period_label, batch_id ),
ps_current_metrics as ( select period_label, batch_id, feed_total, case when total_growth_period > 0 then (total_feed_period/total_growth_period)::double precision else null::double precision end as efcr_period, sgr_period, agr_period from ps_period_metrics where period_label = 'current' ),
ps_prev_metrics as ( select period_label, batch_id, feed_total, case when total_growth_period > 0 then (total_feed_period/total_growth_period)::double precision else null::double precision end as efcr_period, sgr_period, agr_period from ps_period_metrics where period_label = 'previous' ),
wq_window as ( select p.period_label, bs.batch_id, wq.rating_date, wq.rating_numeric, wq.worst_parameter, wq.worst_parameter_value, wq.worst_parameter_unit, wq.created_at, wq.id from periods p join public.daily_water_quality_rating wq on wq.rating_date between p.start_date and p.end_date join batch_systems bs on bs.system_id = wq.system_id ),
wq_avg as ( select period_label, batch_id, avg(rating_numeric::double precision) as rating_numeric_avg, case when avg(rating_numeric::double precision) >= 2.5 then 'Optimal' when avg(rating_numeric::double precision) >= 1.5 then 'Acceptable' when avg(rating_numeric::double precision) >= 0.5 then 'Critical' else 'Lethal' end as rating_label_avg from wq_window group by period_label, batch_id ),
wq_current_avg as (select * from wq_avg where period_label = 'current'),
wq_prev_avg as (select * from wq_avg where period_label = 'previous'),
wq_ranked as ( select wq.period_label, wq.batch_id, wq.rating_date, wq.worst_parameter, wq.worst_parameter_value, wq.worst_parameter_unit, row_number() over ( partition by wq.period_label, wq.batch_id order by wq.rating_date desc, wq.rating_numeric asc, wq.created_at desc, wq.id desc ) as rn from wq_window wq ),
wq_latest as (select * from wq_ranked where period_label = 'current' and rn = 1),
batch_cycles as ( select pc.batch_id, pc.cycle_start, pc.target_weight_g from public.production_cycle pc join batches_all ba on ba.batch_id = pc.batch_id where pc.ongoing_cycle = true ) select batch.batch_id, batch.batch_name, batch.growth_stage, batch.system_ids, batch.system_count, b.start_date as input_start_date, b.end_date as input_end_date, b.end_date as as_of_date, inv_latest.fish_end, inv_latest.biomass_end, inv_latest.sampling_end_date, case when inv_latest.sampling_end_date is null then null else (b.end_date - inv_latest.sampling_end_date)::integer end as sample_age_days, case when ps_latest.biomass_increase_over_period > 0 then (ps_latest.feed_over_period / ps_latest.biomass_increase_over_period)::double precision else null::double precision end as efcr, ps_latest.date as efcr_latest_date, case when ps_current_metrics.efcr_period is null or ps_prev_metrics.efcr_period is null then null when ps_current_metrics.efcr_period = ps_prev_metrics.efcr_period then 'straight' when ps_current_metrics.efcr_period > ps_prev_metrics.efcr_period then 'up' else 'down' end as efcr_arrow, ps_current_metrics.feed_total, inv_latest.abw, inv_latest.sampling_end_date as abw_latest_date, case when inv_latest.abw is null or inv_prev.abw is null then null when inv_latest.abw = inv_prev.abw then 'straight' when inv_latest.abw > inv_prev.abw then 'up' else 'down' end as abw_arrow, inv_current_metrics.feeding_rate_period as feeding_rate, inv_latest.inventory_date as feeding_rate_latest_date, case when inv_current_metrics.feeding_rate_period is null or inv_prev_metrics.feeding_rate_period is null then null when inv_current_metrics.feeding_rate_period = inv_prev_metrics.feeding_rate_period then 'straight' when inv_current_metrics.feeding_rate_period > inv_prev_metrics.feeding_rate_period then 'up' else 'down' end as feeding_rate_arrow, inv_latest.mortality_rate, inv_latest.inventory_date as mortality_rate_latest_date, case when inv_current_metrics.mortality_rate_period is null or inv_prev_metrics.mortality_rate_period is null then null when inv_current_metrics.mortality_rate_period = inv_prev_metrics.mortality_rate_period then 'straight' when inv_current_metrics.mortality_rate_period > inv_prev_metrics.mortality_rate_period then 'up' else 'down' end as mortality_rate_arrow, inv_latest.biomass_density, inv_latest.inventory_date as biomass_density_latest_date, case when inv_current_metrics.biomass_density_period is null or inv_prev_metrics.biomass_density_period is null then null when inv_current_metrics.biomass_density_period = inv_prev_metrics.biomass_density_period then 'straight' when inv_current_metrics.biomass_density_period > inv_prev_metrics.biomass_density_period then 'up' else 'down' end as biomass_density_arrow, ps_current_metrics.sgr_period as sgr, ps_current_metrics.agr_period as agr, case when ps_current_metrics.sgr_period is null or ps_prev_metrics.sgr_period is null then null when ps_current_metrics.sgr_period > ps_prev_metrics.sgr_period then 'up' when ps_current_metrics.sgr_period < ps_prev_metrics.sgr_period then 'down' else 'straight' end as sgr_arrow, case when ps_current_metrics.agr_period is null or ps_prev_metrics.agr_period is null then null when ps_current_metrics.agr_period > ps_prev_metrics.agr_period then 'up' when ps_current_metrics.agr_period < ps_prev_metrics.agr_period then 'down' else 'straight' end as agr_arrow, greatest(0, (b.end_date - b.start_date + 1)::integer - coalesce(inv_agg.days_present, 0)) as missing_days_count, wq_current_avg.rating_label_avg as water_quality_rating_average, wq_current_avg.rating_numeric_avg as water_quality_rating_numeric_average, wq_latest.rating_date as water_quality_latest_date, case when wq_current_avg.rating_numeric_avg is null or wq_prev_avg.rating_numeric_avg is null then null when wq_current_avg.rating_numeric_avg = wq_prev_avg.rating_numeric_avg then 'straight' when wq_current_avg.rating_numeric_avg > wq_prev_avg.rating_numeric_avg then 'up' else 'down' end as water_quality_arrow, wq_latest.worst_parameter, wq_latest.worst_parameter_value, wq_latest.worst_parameter_unit, case when bc.cycle_start is null then null else (b.end_date - bc.cycle_start)::integer end as cycle_day, bc.target_weight_g::double precision as target_weight_g, case when bc.target_weight_g is not null and inv_latest.abw is not null then round((inv_latest.abw / bc.target_weight_g::double precision * 100)::numeric, 1)::double precision else null end as target_weight_progress_pct, case when inv_latest.fish_end is not null and inv_latest.fish_end > 0 and inv_latest.biomass_end is not null and ps_current_metrics.feed_total is not null and ps_latest.biomass_increase_over_period is not null and ps_latest.biomass_increase_over_period > 0 and inv_latest.abw is not null and inv_latest.biomass_density is not null then true else false end as is_complete from batch cross join bounds b left join inv_latest on inv_latest.batch_id = batch.batch_id left join inv_prev on inv_prev.batch_id = batch.batch_id left join inv_agg on inv_agg.batch_id = batch.batch_id left join ps_latest on ps_latest.batch_id = batch.batch_id left join inv_current_metrics on inv_current_metrics.batch_id = batch.batch_id left join inv_prev_metrics on inv_prev_metrics.batch_id = batch.batch_id left join ps_current_metrics on ps_current_metrics.batch_id = batch.batch_id left join ps_prev_metrics on ps_prev_metrics.batch_id = batch.batch_id left join wq_current_avg on wq_current_avg.batch_id = batch.batch_id left join wq_prev_avg on wq_prev_avg.batch_id = batch.batch_id left join wq_latest on wq_latest.batch_id = batch.batch_id left join batch_cycles bc on bc.batch_id = batch.batch_id order by batch.batch_name; $function$;
